meta.script:
(function(){
  var MIN=1100, MAX=1205;
  var D=[
    ["GPT Image 2.5 Sunburst (max)",1199,0,"#E6CAD1"],
    ["MAI-Image-2.7-Preview",1193,1,"#738C7B"],
    ["GPT Image 2.5 Flare (max)",1182,0,"#FBCFB9"],
    ["MAI-Image-2.6",1151,0,"#AFC3B5"],
    ["Krea 3 (Ultra)",1151,0,"#99BFBF"],
    ["Nano Banana 2.1",1151,0,"#E6CAD1"],
    ["MAI-Image-2.6-Flash",1144,0,"#AFC3B5"],
    ["GPT Image 2 (high)",1136,0,"#FBCFB9"]
  ];
  var TICKS=[1100,1120,1140,1160,1180,1200];
  var MTICKS=[1100,1150,1200];

  var root=document.getElementById("maiElo"), plot=document.getElementById("elPlot");
  if(!root||!plot) return;
  function el(t,c){ var n=document.createElement(t); if(c) n.className=c; return n; }
  function mob(){ return window.matchMedia("(max-width:600px)").matches; }
  var pct=function(v){ return (v-MIN)/(MAX-MIN)*100; };
  var bars=[], vals=[];

  function build(){
    plot.innerHTML=""; bars=[]; vals=[];
    var m=mob();
    var grid=el("div","el-grid");

    D.forEach(function(d,i){
      var row=el("div","el-row"+(d[2]?" is-mai":""));
      var nm=el("div","el-name"); nm.textContent=d[0];
      var tr=el("div","el-track");
      var bar=el("div","el-bar"); bar.style.background=d[3]; bar.style.transitionDelay=(i*70)+"ms";
      tr.appendChild(bar);
      var vl=el("div","el-val"); vl.textContent=MIN; vl.style.transitionDelay=(i*70+260)+"ms";
      row.appendChild(nm); row.appendChild(tr); row.appendChild(vl);
      grid.appendChild(row);
      bars.push([bar,d[1]]); vals.push([vl,d[1]]);
    });
    plot.appendChild(grid);

    var ax=el("div","el-axis");
    if(!m) ax.appendChild(el("div"));
    var tk=el("div","el-ticks");
    (m?MTICKS:TICKS).forEach(function(v){
      var t=el("div","el-tk"); t.textContent=v.toLocaleString();
      t.style.left=pct(v)+"%"; tk.appendChild(t);
    });
    ax.appendChild(tk); ax.appendChild(el("div"));
    plot.appendChild(ax);

    // gridlines behind the bars, aligned to the ticks
    (m?MTICKS:TICKS).forEach(function(v){
      var g=el("div","el-gl"); g.style.left="calc("+pct(v)+"% )";
      grid.appendChild(g);
    });
    positionGrid(grid, m);
  }

  function positionGrid(grid,m){
    // gridlines span the plot column only
    var first=grid.querySelector(".el-track");
    if(!first) return;
    var gr=grid.getBoundingClientRect(), tr=first.getBoundingClientRect();
    var left=tr.left-gr.left, w=tr.width;
    [].forEach.call(grid.querySelectorAll(".el-gl"),function(g,i){
      var v=(m?MTICKS:TICKS)[i];
      g.style.left=(left + w*(v-MIN)/(MAX-MIN))+"px";
    });
  }

  function run(){
    root.classList.add("is-in");
    bars.forEach(function(b){ b[0].style.width=pct(b[1])+"%"; });
    var reduced=window.matchMedia&&window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    if(reduced){ vals.forEach(function(v){ v[0].textContent=v[1].toLocaleString(); }); return; }
    var t0=0;
    function tick(ts){
      if(!t0) t0=ts;
      var e=ts-t0, done=true;
      vals.forEach(function(v,i){
        var st=i*70, p=Math.min(1,Math.max(0,(e-st)/1000));
        if(p<1) done=false;
        var k=1-Math.pow(1-p,3);
        v[0].textContent=Math.round(MIN+(v[1]-MIN)*k).toLocaleString();
      });
      if(!done) requestAnimationFrame(tick);
    }
    requestAnimationFrame(tick);
  }

  var wasMob=null, raf;
  function relayout(){
    cancelAnimationFrame(raf);
    raf=requestAnimationFrame(function(){
      var m=mob();
      if(m!==wasMob){
        wasMob=m; build();
        if(root.classList.contains("is-in")){
          bars.forEach(function(b){ b[0].style.transitionDelay="0ms"; b[0].style.width=pct(b[1])+"%"; });
          vals.forEach(function(v){ v[0].textContent=v[1].toLocaleString(); });
        }
      } else {
        positionGrid(plot.querySelector(".el-grid"), m);
      }
    });
  }
  relayout();
  if(window.ResizeObserver){ new ResizeObserver(relayout).observe(plot); }
  else { window.addEventListener("resize",relayout); }

  if("IntersectionObserver" in window){
    var io=new IntersectionObserver(function(es){
      es.forEach(function(e){ if(e.isIntersecting){ io.unobserve(e.target); run(); } });
    },{threshold:0, rootMargin:"0px 0px -8% 0px"});
    io.observe(root);
  } else { run(); }
})();
